begin;
select no_plan();
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('ed230000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer,org integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'role','authenticated','org_id',pg_temp.id(org))::text,true)::void$$;
insert into auth.users(id,email) select pg_temp.id(n),'driver-'||n||'@test.local' from generate_series(10,16) n;
insert into public.organizations(id,slug,name) values(pg_temp.id(1),'driver-a','Driver A'),(pg_temp.id(2),'driver-b','Driver B');
insert into public.memberships(organization_id,user_id,role) values
 (pg_temp.id(1),pg_temp.id(10),'owner'),(pg_temp.id(1),pg_temp.id(11),'viewer'),(pg_temp.id(1),pg_temp.id(12),'branch_user'),
 (pg_temp.id(2),pg_temp.id(13),'owner'),(pg_temp.id(1),pg_temp.id(14),'planner'),(pg_temp.id(1),pg_temp.id(15),'approver'),(pg_temp.id(1),pg_temp.id(16),'admin');
insert into public.locations(id,organization_id,code,name_en,location_type,country_code,timezone)
 select pg_temp.id(20+n),pg_temp.id(case when n=2 then 2 else 1 end),'L'||n,'Location','branch','SA','Asia/Riyadh' from generate_series(0,2) n;
insert into public.items(id,organization_id,code,name_en,product_group,unit_of_measure,unit_cost,currency)
 values(pg_temp.id(30),pg_temp.id(1),'P1','Part','Test','EA',1,'SAR');
insert into public.membership_locations values(pg_temp.id(1),pg_temp.id(12),pg_temp.id(21));
create temporary table fixture(input jsonb,report jsonb,saved uuid);
insert into fixture(input) values('{"item_code":"P1","location_code":"L0","driver_name":"Temperature","unit":"degrees C","source":"Test source","history_from":"2026-01-01","cutoff":"2026-01-02","forecast_to":"2026-01-04","confirmed":true,"rows":[{"date":"2026-01-01","value":"-0.123456","kind":"observed","available_on":"2026-01-01"},{"date":"2026-01-03","value":"999999999999.999999","kind":"observed","available_on":"2026-01-04"},{"date":"2026-01-04","value":"0","kind":"planned","available_on":"2026-01-02"}]}');
grant all on fixture to authenticated;
create function pg_temp.preview(overrides jsonb default '{}') returns jsonb language sql as $$select public.external_driver_preview(pg_temp.id(1),input||overrides) from fixture$$;
create function pg_temp.save(n integer default 40, overrides jsonb default '{}', fingerprint text default null) returns uuid language sql as $$select public.external_driver_save(pg_temp.id(1),input||overrides,pg_temp.id(n),coalesce(fingerprint,report->>'fingerprint')) from fixture$$;
select pg_temp.login(10,1); set local role authenticated;
update fixture set report=pg_temp.preview();
select is((select jsonb_array_length(report->'daily') from fixture),4,'complete selected window is represented');
select is((select report#>>'{daily,0,value}' from fixture),'-0.123456','negative exact driver values retained');
select is((select report#>>'{daily,1,availability}' from fixture),'missing','gap remains unknown');
select is((select report#>'{daily,1,value}' from fixture),'null'::jsonb,'missing is not zero');
select is((select report#>>'{daily,2,value}' from fixture),'999999999999.999999','precision beyond binary float preserved');
select is((select report#>>'{daily,2,availability}' from fixture),'after_cutoff','retrospective observation not labelled available at cutoff');
select is((select report#>>'{daily,3,availability}' from fixture),'declared_available','same-day declared availability included');
select is((select report#>>'{daily,3,kind}' from fixture),'planned','future assumption not relabelled observed');
select is(pg_temp.preview('{"confirmed":false}')#>>'{input,confirmed}','false','unconfirmed preview is inspectable');
select throws_ok($$select pg_temp.save(40,'{"confirmed":false}')$$,'MQ422','invalid driver save','confirmation needed to save');
select throws_ok($$select pg_temp.preview('{"rows":[]}')$$,'MQ422','invalid driver window','empty dataset rejected');
select throws_ok($$select pg_temp.preview('{"rows":null}')$$,'MQ422','invalid driver input','null dataset rejected');
select throws_ok($$select pg_temp.preview('{"unit":42}')$$,'MQ422','invalid driver metadata','unit must be supplied text');
select throws_ok($$select pg_temp.preview('{"unit":" "}')$$,'MQ422','invalid driver metadata','unit is required');
select throws_ok($$select pg_temp.preview('{"history_from":"2026-02-30"}')$$,'MQ422','invalid driver dates','invalid date rejected');
select throws_ok($$select pg_temp.preview('{"history_from":"2022-01-01"}')$$,'MQ422','invalid driver window','history bounded');
select throws_ok($$select pg_temp.preview('{"forecast_to":"2027-01-01"}')$$,'MQ422','invalid driver window','forecast horizon bounded');
select throws_ok($$select pg_temp.preview('{"forecast_to":"2026-01-02"}')$$,'MQ422','invalid driver window','forecast horizon positive');
select throws_ok($$select pg_temp.preview('{"rows":[{"date":"2026-01-01","value":"1e2","kind":"observed","available_on":"2026-01-01"}]}')$$,'MQ422','invalid driver row','scientific notation rejected');
select throws_ok($$select pg_temp.preview('{"rows":[{"date":"2026-01-01","value":1,"kind":"observed","available_on":"2026-01-01"}]}')$$,'MQ422','invalid driver row','numbers must use exact strings');
select throws_ok($$select pg_temp.preview('{"rows":[{"date":"2026-01-01","value":"NaN","kind":"planned","available_on":"2026-01-01"}]}')$$,'MQ422','invalid driver row','NaN rejected');
select throws_ok($$select pg_temp.preview('{"rows":[{"date":"2026-01-01","value":"0.0000001","kind":"planned","available_on":"2026-01-01"}]}')$$,'MQ422','invalid driver row','extra precision not rounded');
select throws_ok($$select pg_temp.preview('{"rows":[{"date":"2026-01-01","value":"1000000000000","kind":"planned","available_on":"2026-01-01"}]}')$$,'MQ422','invalid driver row','oversized integer rejected');
select throws_ok($$select pg_temp.preview('{"rows":[{"date":"2026-01-01","value":"1","kind":"actual","available_on":"2026-01-01"}]}')$$,'MQ422','invalid driver row','unknown kind rejected');
select throws_ok($$select pg_temp.preview('{"rows":[{"date":"2026-01-01","value":"1","kind":"observed","available_on":"2025-12-31"}]}')$$,'MQ422','incompatible driver dates','observation cannot be known before its date');
select throws_ok($$select pg_temp.preview('{"rows":[{"date":"2025-12-31","value":"1","kind":"planned","available_on":"2025-12-31"}]}')$$,'MQ422','incompatible driver dates','outside window rejected');
select throws_ok($$select pg_temp.preview('{"rows":[{"date":"2026-01-01","value":"1","kind":"planned","available_on":"9999-12-31"}]}')$$,'MQ422','driver availability cannot be in the future','future knowledge claim rejected');
select throws_ok($$select pg_temp.preview(jsonb_build_object('rows',jsonb_build_array(input#>'{rows,0}',input#>'{rows,0}'))) from fixture$$,'MQ422','duplicate driver dates','duplicates rejected');
select throws_ok($$select public.external_driver_preview(pg_temp.id(1),'null')$$,'MQ422','invalid driver input','scalar RPC input rejected');
select throws_ok($$select pg_temp.preview(jsonb_build_object('source',repeat('x',525000)))$$,'MQ422','invalid driver input','input size bounded');
update fixture set saved=pg_temp.save();
select is(pg_temp.save(),(select saved from fixture),'identical retry returns saved dataset');
select is(pg_temp.save(40,jsonb_build_object('rows',jsonb_build_array(input#>'{rows,2}',input#>'{rows,0}',input#>'{rows,1}'))),(select saved from fixture),'row ordering does not change retry identity') from fixture;
select throws_ok($$select pg_temp.save(40,'{"driver_name":"Different"}')$$,'MQ409','driver request conflicts','conflicting retry rejected');
select throws_ok($$select pg_temp.save(41,'{}',repeat('a',64))$$,'MQ409','driver evidence changed; refresh preview','forged preview rejected');
select is((select count(*)::integer from public.external_driver_datasets),1,'only one dataset stored');
select ok((select created_at <= clock_timestamp() and created_at >= transaction_timestamp() from public.external_driver_datasets),'server assigns import timestamp');
select throws_ok($$insert into public.external_driver_datasets default values$$,'42501',null,'direct insert denied');
select throws_ok($$update public.external_driver_datasets set driver_name='x'$$,'42501',null,'direct updates denied');
select throws_ok($$delete from public.external_driver_datasets$$,'42501',null,'direct deletion denied');
select throws_ok($$select app.external_driver_input('{}')$$,'42501',null,'private normalizer not exposed');
select pg_temp.login(11,1);
select is((select count(*)::integer from public.external_driver_datasets),1,'viewer reads history');
select throws_ok($$select pg_temp.save()$$,'MQ403','driver save forbidden','viewer cannot retry a save');
select pg_temp.login(15,1);
select throws_ok($$select pg_temp.save()$$,'MQ403','driver save forbidden','approver cannot save');
select pg_temp.login(12,1);
select is((select count(*)::integer from public.external_driver_datasets),0,'restricted branch cannot read other location');
select throws_ok($$select pg_temp.preview()$$,'MQ404','driver source unavailable','definer preview enforces branch scope');
select pg_temp.login(13,2);
select is((select count(*)::integer from public.external_driver_datasets),0,'other tenant cannot read datasets');
select throws_ok($$select pg_temp.save()$$,'MQ403','driver save forbidden','cross tenant save denied');
select pg_temp.login(10,2);
select throws_ok($$select pg_temp.preview()$$,'MQ404','driver source unavailable','active organization mismatch denied');
reset role;
insert into public.membership_locations values(pg_temp.id(1),pg_temp.id(12),pg_temp.id(20));
select pg_temp.login(12,1); set local role authenticated;
select is((select count(*)::integer from public.external_driver_datasets),1,'branch reads after scope granted');
reset role;
update public.items set name_en='Changed' where id=pg_temp.id(30);
select pg_temp.login(10,1); set local role authenticated;
select throws_ok($$select pg_temp.save(42)$$,'MQ409','driver evidence changed; refresh preview','changed catalog evidence needs refresh');
select is(pg_temp.save(),(select saved from fixture),'historical retry remains stable after catalog change');
select is((select report#>>'{source,item_name}' from public.external_driver_datasets),'Part','saved catalog evidence fixed');
update fixture set report=pg_temp.preview();
select pg_temp.login(14,1);
select lives_ok($$select pg_temp.save(43)$$,'planner saves new dataset');
select pg_temp.login(16,1);
select lives_ok($$select pg_temp.save(44)$$,'admin saves new dataset');
reset role;
delete from public.items where id=pg_temp.id(30);
select pg_temp.login(10,1); set local role authenticated;
select is((select count(*)::integer from public.external_driver_datasets),3,'datasets survive item deletion');
select is(pg_temp.save(40,'{}',(select report->>'fingerprint' from public.external_driver_datasets where id=(select saved from fixture))),(select saved from fixture),'retry original remains independent of item deletion');
select is((select count(*)::integer from public.planning_runs where organization_id=pg_temp.id(1)),0,'no forecasts queued');
select is((select count(*)::integer from public.inventory_policies where organization_id=pg_temp.id(1)),0,'no policies created');
select is((select count(*)::integer from public.open_orders where organization_id=pg_temp.id(1)),0,'no orders created');
reset role;
update public.memberships set role='viewer' where organization_id=pg_temp.id(1) and user_id=pg_temp.id(10);
select pg_temp.login(10,1); set local role authenticated;
select throws_ok($$select pg_temp.save()$$,'MQ403','driver save forbidden','revoked editor cannot retry');
reset role;
delete from public.locations where id=pg_temp.id(20);
select is((select count(*)::integer from public.external_driver_datasets),0,'location deletion cascades datasets');
select * from finish();
rollback;
